# ==========================================
# INIMIGO 5: COMBATENT (Guarda da Porta)
# ==========================================
# Fica parado logo na frente da torre (-450)
ENTITY combatent1
# TRANSFORM com yaw = PI (180 graus, olhando para trás)
TRANSFORM 0.0 0.0 -450.0 PI
PHYSICS 0.0 0.0 0.0 0.90
COLLISION -7.0 0.2 -7.0 7.0 23.9 7.0 0 0
HEALTH 150.0
RENDER 1 255 255 255 255
AI_CONTROL 150.0 75.0

ENTITY comb1_gun
TRANSFORM 0 0 0
# Atira mais rápido (0.2s)
WEAPON WEAPON_PULSE_LASER 0.3 250.0 5.0 500.0 2.0 2 0.1
ATTACHMENT combatent1 6.25 15.50 0.00
LINK_WEAPON combatent1 0 comb1_gun 0 1


